async(page)=>{
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});
 await page.locator('[data-role=dispatch]').first().click();await page.locator('[data-dispatch-tab=orders]').click();await page.locator('[data-action=qa]').click();await page.locator('[data-action=reset]').click();await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'});await page.locator('[data-role=dispatch]').first().click();await page.locator('[data-dispatch-tab=orders]').click();await page.locator('[data-action=offer]').click();await page.locator('[name=vehicle][value=V01]').check();await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'});await page.locator('[data-role=driver]').first().click();await page.setViewportSize({width:390,height:844});
 const svg=page.locator('#driver-map-canvas'),first=await svg.getAttribute('viewBox');await page.getByRole('button',{name:'放大地图',exact:true}).click();if(await svg.getAttribute('viewBox')===first)throw Error('zoom failed');await page.getByRole('button',{name:'回到司机演示位置',exact:true}).click();if(await svg.getAttribute('viewBox')!==first)throw Error('center failed');if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('overflow');
 if(!await page.locator('[data-action=accept]').isVisible())throw Error('task action missing');await page.waitForTimeout(4600);await page.screenshot({path:'E:/Dr.RouteFit/prototype/screenshots/driver-map-home.png',fullPage:true});return {status:'PASS',checks:['driver position and pickup/dropoff map','zoom and recenter','task acceptance available','390px no overflow']};
}
